func (h Handle) Dger(m int32, n int32, alpha *float64, x driver.DevicePtr, incx int32, y driver.DevicePtr, incy int32, a driver.DevicePtr, lda int32) error {
	return dger(h, m, n, alpha, x, incx, y, incy, a, lda)
}

